// AP Physics C: Electricity and Magnetism — original practice question bank
// Unofficial questions aligned to the Fall 2026 CED and May 2027 exam format.
// No released or secure College Board question is reproduced here.
const E = [];
function add(id, unit, topicCode, topic, skill, q, correct, d1, d2, d3, e) {
  const options = [correct, d1, d2, d3];
  const shift = E.length % 4;
  const rotated = options.slice(shift).concat(options.slice(0, shift));
  E.push({ id, unit, topicCode, topic, skill, type:"s", q, o:rotated, c:[(4-shift)%4], e });
}
add("em-8.1-01","U8","8.1","Electric Charge and Electric Force","2.B","Two point charges +2.0 μC and −3.0 μC are 0.50 m apart. What is the magnitude of the electric force between them?","0.216 N","0.108 N","0.432 N","2.16 N","Coulomb’s law gives F = k|q₁q₂|/r² = (8.99×10⁹)(6.0×10⁻¹²)/(0.50)² ≈ 0.216 N; the opposite signs affect direction, not magnitude.");
add("em-8.1-02","U8","8.1","Electric Charge and Electric Force","2.D","If both point charges are doubled while their separation is tripled, by what factor does the electric-force magnitude change?","4/9","2/3","4/3","9/4","Because Coulomb force scales as q₁q₂/r², doubling each charge contributes a factor of 4 while tripling separation contributes 1/9, for a net factor 4/9.");
add("em-8.1-03","U8","8.1","Electric Charge and Electric Force","3.B","Two positive point charges lie on the x-axis. At a point exactly midway between them, the net electric force on a positive test charge is zero only if which condition is met?","The two source charges have equal magnitude","The two source charges have equal mass","The test charge is infinitesimal","The source charges are fixed in place","At the midpoint the distances to the sources are equal, so their oppositely directed Coulomb forces cancel only when the source-charge magnitudes are equal.");
add("em-8.1-04","U8","8.1","Electric Charge and Electric Force","2.A","A uniformly charged ring of radius R has total charge Q. Which integral correctly represents the axial force on charge q a distance x from its center?","∫ kq x dq'/(x²+R²)^(3/2)","∫ kq dq'/(x²+R²)","∫ kq R dq'/(x²+R²)^(3/2)","∫ kq x dq'/(x²+R²)","Each ring element is the same distance √(x²+R²) from q, and only the axial component survives symmetry, adding the projection factor x/√(x²+R²) to Coulomb’s law.");
add("em-8.2-01","U8","8.2","Conservation of Electric Charge and the Process of Charging","3.B","A neutral conducting sphere is touched by a negatively charged conducting sphere and then separated. Which statement best describes the neutral sphere afterward?","It acquires negative charge while total charge of the two-sphere system is conserved","It becomes positively charged because electrons leave it","It remains neutral because charge cannot move between conductors","Its final charge must equal the original charge of the other sphere","Contact allows mobile electrons to redistribute between the conductors, so the initially neutral sphere can become negative while the total charge of the isolated two-sphere system remains unchanged.");
add("em-8.2-02","U8","8.2","Conservation of Electric Charge and the Process of Charging","2.C","Identical neutral metal spheres A and B are separated. A negatively charged rod is brought near A, the spheres are briefly connected, then disconnected before the rod is removed. Compared with B, sphere A ends with","less negative charge, because electrons were repelled toward B","more negative charge, because electrons were attracted toward the rod","the same charge, because the spheres are identical","zero charge, because induction cannot charge conductors","The nearby negative rod repels mobile electrons away from A through the temporary connection, so B gains electrons and A is left relatively positive compared with B after disconnection.");
add("em-8.2-03","U8","8.2","Conservation of Electric Charge and the Process of Charging","2.B","A conducting object initially has charge +6e. It gains four electrons. What is its final charge?","+2e","+10e","−2e","−10e","Each added electron contributes charge −e, so the object’s charge changes by −4e: +6e − 4e = +2e, consistent with charge quantization and conservation.");
add("em-8.2-04","U8","8.2","Conservation of Electric Charge and the Process of Charging","3.C","A student says rubbing two initially neutral insulators creates positive charge on one and negative charge on the other. Which observation best supports charge conservation?","The measured charges are equal in magnitude and opposite in sign","Both objects attract small neutral paper pieces","The objects repel after being brought close together","The rubbing process raises the temperature of both objects","Equal and opposite measured charges show that charge was transferred between the objects rather than created, so the net charge of the isolated pair remains zero.");
add("em-8.3-01","U8","8.3","Electric Fields","2.B","A +3.0 μC point charge creates an electric field at a point 0.20 m away. What is the field magnitude?","6.74×10⁵ N/C","3.37×10⁵ N/C","1.35×10⁶ N/C","6.74×10⁴ N/C","For a point charge, E = k|Q|/r² = (8.99×10⁹)(3.0×10⁻⁶)/(0.20)² ≈ 6.74×10⁵ N/C, directed radially outward for positive Q.");
add("em-8.3-02","U8","8.3","Electric Fields","2.C","At the same distance from isolated charges +Q and −2Q, how do the electric-field magnitudes compare?","The field from −2Q is twice as large","The field from +Q is twice as large","The magnitudes are equal but directions differ","The comparison depends on the test charge used","Point-charge field magnitude is k|Q|/r², so doubling source-charge magnitude doubles field magnitude at the same radius; field is a property of the source configuration, not the test charge.");
add("em-8.3-03","U8","8.3","Electric Fields","3.B","A proton is released from rest in a uniform electric field directed east. Neglecting gravity, its initial acceleration is","east, because F = qE and the proton has positive charge","west, because electric force opposes electric field","zero, because the proton begins at rest","north, because electric force is perpendicular to electric field","For a positive charge, electric force qE points with the field; Newton’s second law then gives acceleration in the same eastward direction regardless of the initial velocity.");
add("em-8.3-04","U8","8.3","Electric Fields","2.A","For an infinite line with uniform linear charge density λ, which expression gives the field a perpendicular distance r away?","E = λ/(2πε₀r)","E = λ/(4πε₀r²)","E = λr/(2πε₀)","E = λ/(ε₀r²)","Cylindrical symmetry makes the field radial and constant on a coaxial Gaussian cylinder; flux E(2πrL) equals λL/ε₀, yielding E = λ/(2πε₀r).");

add("em-8.4-01","U8","8.4","Electric Fields of Charge Distributions","2.A","A thin rod lies along the x-axis from x=0 to x=L with uniform linear charge density λ. For an observation point at x=a>L, which differential expression gives the field contribution from an element dx?","dE = kλ dx/(a−x)² in the +x direction","dE = kλ dx/(a−x) in the +x direction","dE = kλ(a−x) dx in the +x direction","dE = kλ dx/(a²+x²) in the +x direction","The charge element is dq=λdx and its distance from the observation point is a−x, so Coulomb's law gives k dq/(a−x)² directed away from the positive element along +x.");
add("em-8.4-02","U8","8.4","Electric Fields of Charge Distributions","3.B","At the exact center of a uniformly charged circular ring, the electric field is zero because","fields from diametrically opposite charge elements cancel vectorially","each charge element produces zero electric field at the center","the ring contains equal positive and negative charge","electric field cannot exist inside a charged object","Every charge element has a diametrically opposite element at the same distance producing an equal field in the opposite direction, so the vector sum vanishes by symmetry.");
add("em-8.4-03","U8","8.4","Electric Fields of Charge Distributions","2.C","Two uniformly charged rings have equal total charge but different radii. At the exact center of each ring, how do their electric-field magnitudes compare?","They are equal and both zero","The smaller ring has the larger field","The larger ring has the larger field","The comparison depends on the sign of the charge","Circular symmetry cancels contributions from opposite elements at the center of either uniformly charged ring, so both net electric fields are exactly zero regardless of radius.");
add("em-8.4-04","U8","8.4","Electric Fields of Charge Distributions","2.D","Far from a localized charge distribution with nonzero total charge Q, increasing the observation distance by a factor of 3 changes the leading electric-field magnitude by approximately","a factor of 1/9","a factor of 1/3","a factor of 3","a factor of 9","At distances much larger than the distribution size, its leading field is the monopole field of total charge Q, so E scales as 1/r² and falls to one ninth when r triples.");
add("em-8.5-01","U8","8.5","Electric Flux","2.B","A uniform electric field of 200 N/C passes through a flat area of 0.30 m². The field makes a 60° angle with the area vector. What is the electric flux?","30 N·m²/C","60 N·m²/C","52 N·m²/C","120 N·m²/C","Electric flux through a flat surface is Φ=EA cosθ=(200)(0.30)cos60°=30 N·m²/C, with θ measured from the surface's area vector.");
add("em-8.5-02","U8","8.5","Electric Flux","2.C","The same uniform electric field passes through two equal flat surfaces. Surface A has its area vector parallel to the field; surface B has its area vector perpendicular to the field. Compared with A, the flux through B is","zero","the same","half as large","twice as large","Flux is EA cosθ. A parallel area vector has θ=0 and maximum flux, whereas a perpendicular area vector has θ=90° and therefore zero flux.");
add("em-8.5-03","U8","8.5","Electric Flux","3.B","A closed surface encloses no net charge but has several external point charges nearby. Which statement about the total electric flux through the surface is correct?","The net flux is zero even though the field can be nonzero on the surface","The net flux must be positive because field lines enter the surface","The net flux depends on the surface area","The net flux equals the external charge magnitude divided by ε₀","Gauss's law relates total closed-surface flux only to enclosed net charge. External charges can create local fields, but their entering and leaving flux contributions sum to zero.");
add("em-8.5-04","U8","8.5","Electric Flux","2.D","For fixed uniform electric-field magnitude and fixed flat area, rotating the area vector from 0° to 60° relative to the field changes the flux by what factor?","1/2","√3/2","2","4","With E and A fixed, flux scales as cosθ; changing from cos0°=1 to cos60°=1/2 reduces the electric flux to one half of its original value.");
add("em-8.6-01","U8","8.6","Gauss's Law","2.B","A spherical Gaussian surface encloses a point charge +4.0 nC. What is the net electric flux through the surface?","4.52×10² N·m²/C","2.26×10² N·m²/C","9.04×10² N·m²/C","4.52×10⁻² N·m²/C","Gauss's law gives Φ=Qenc/ε₀=4.0×10⁻⁹/(8.85×10⁻¹²)≈4.52×10² N·m²/C, independent of sphere radius or the charge's position inside.");
add("em-8.6-02","U8","8.6","Gauss's Law","2.A","A uniformly charged solid sphere has radius R and total charge Q. For r<R, which expression gives the electric-field magnitude?","E = Qr/(4πε₀R³)","E = Q/(4πε₀r²)","E = Qr²/(4πε₀R⁴)","E = QR/(4πε₀r³)","Uniform volume charge gives Qenc=Q(r³/R³). Substitution into E(4πr²)=Qenc/ε₀ yields E=Qr/(4πε₀R³), so the interior field grows linearly with r.");
add("em-8.6-03","U8","8.6","Gauss's Law","3.C","A student chooses a cubic Gaussian surface around a point charge at its center and says Gauss's law cannot be used because the field is not constant over each face. Which response is best?","Gauss's law still fixes total flux, although the cube does not make the field easy to extract from the integral","Gauss's law is valid only for spherical or cylindrical surfaces","The cube gives zero net flux because opposite faces cancel","The law fails whenever electric field is not perpendicular to a surface","Gauss's law applies to every closed surface, but symmetry is needed to pull E outside the flux integral; a cube therefore gives correct total flux without directly yielding a simple E value.");
add("em-8.6-04","U8","8.6","Gauss's Law","2.C","A point charge q is first centered inside a spherical Gaussian surface and then moved off center while remaining inside. How does the total electric flux through the sphere change?","It does not change","It increases","It decreases","It becomes zero","The enclosed charge remains q in both cases, so Gauss's law fixes the same total flux q/ε₀ even though moving the charge changes how flux is distributed over the surface.");


add("em-9.1-01","U9","9.1","Electric Potential Energy","2.B","Two point charges +2.0 μC and +3.0 μC are separated by 0.40 m. What is their electric potential energy relative to infinite separation?","0.135 J","−0.135 J","0.0674 J","0.270 J","For two point charges, U=kq₁q₂/r=(8.99×10⁹)(6.0×10⁻¹²)/0.40≈+0.135 J; like charges have positive interaction energy relative to infinity.");
add("em-9.1-02","U9","9.1","Electric Potential Energy","2.D","If the separation between two fixed like point charges is doubled, their electric potential energy becomes","one half as large","one fourth as large","twice as large","unchanged","The point-charge interaction energy U=kq₁q₂/r is inversely proportional to separation, so doubling r reduces U by a factor of two while preserving its positive sign.");
add("em-9.1-03","U9","9.1","Electric Potential Energy","3.B","A negative charge is moved quasistatically closer to a fixed positive charge. Which statement is correct?","The system's electric potential energy decreases","The system's electric potential energy increases","The system's potential energy remains zero","The potential-energy change depends on the path taken","For opposite charges U=kq₁q₂/r is negative; decreasing r makes U more negative, so the system's potential energy decreases independent of path because electrostatic force is conservative.");
add("em-9.1-04","U9","9.1","Electric Potential Energy","2.A","Which expression gives the electric potential energy of three point charges q₁, q₂, and q₃ separated pairwise by distances r₁₂, r₁₃, and r₂₃?","k(q₁q₂/r₁₂ + q₁q₃/r₁₃ + q₂q₃/r₂₃)","k(q₁q₂q₃)/(r₁₂r₁₃r₂₃)","k(q₁+q₂+q₃)/(r₁₂+r₁₃+r₂₃)","k(q₁q₂/r₁₂² + q₁q₃/r₁₃² + q₂q₃/r₂₃²)","Electrostatic potential energy is the sum over distinct interacting charge pairs, with each pair contributing kqᵢqⱼ/rᵢⱼ exactly once rather than using an inverse-square dependence.");
add("em-9.2-01","U9","9.2","Electric Potential","2.B","What electric potential is produced by a +5.0 nC point charge at a distance of 0.20 m, taking zero potential at infinity?","225 V","112 V","450 V","22.5 V","For a point charge, V=kQ/r=(8.99×10⁹)(5.0×10⁻⁹)/0.20≈225 V; potential is a scalar and retains the sign of the source charge.");
add("em-9.2-02","U9","9.2","Electric Potential","2.C","At a point equidistant from charges +Q and −Q, the electric potential is zero. Which statement about the electric field there is necessarily true?","The electric field need not be zero","The electric field must also be zero","The electric field is undefined","The electric field can be zero only if Q=0","Potential adds as a scalar and equal opposite contributions can cancel, while electric field is a vector whose contributions can reinforce; zero potential therefore does not imply zero field.");
add("em-9.2-03","U9","9.2","Electric Potential","2.A","For a one-dimensional electrostatic potential V(x), which relationship gives the x-component of electric field?","Eₓ = −dV/dx","Eₓ = dV/dx","Eₓ = −V/x","Eₓ = ∫V dx","Electric field is the negative spatial gradient of electric potential, so in one dimension Eₓ=−dV/dx; the minus sign points the field toward decreasing potential.");
add("em-9.2-04","U9","9.2","Electric Potential","3.C","A graph of V versus x has a constant positive slope over a region. Which claim about the electric field in that region is best justified?","The field is uniform and points in the negative x-direction","The field is uniform and points in the positive x-direction","The field increases linearly in the positive x-direction","The field is zero because the potential is linear","Because Eₓ=−dV/dx, a constant positive potential slope corresponds to a constant negative electric field, so the field is uniform and directed toward decreasing x.");
add("em-9.3-01","U9","9.3","Conservation of Electric Energy","2.B","A proton moves from a point at 120 V to a point at 20 V. What is the change in its electric potential energy?","−100 eV","+100 eV","−140 eV","+140 eV","For charge +e, ΔU=qΔV=e(20−120)V=−100 eV; the proton loses electric potential energy as it moves to lower electric potential.");
add("em-9.3-02","U9","9.3","Conservation of Electric Energy","3.B","An electron is released from rest in an electrostatic field and moves to a region of higher electric potential. Neglecting other forces, what happens to its kinetic energy?","It increases","It decreases","It remains constant","It must first decrease and then increase","For an electron q<0, moving to higher V makes U=qV decrease. Conservation of mechanical energy therefore requires kinetic energy to increase by the same amount.");
add("em-9.3-03","U9","9.3","Conservation of Electric Energy","2.A","A particle of charge q and mass m starts from rest and moves through a potential difference such that its electric potential energy decreases by magnitude |qΔV|. Which expression gives its final speed?","√(2|qΔV|/m)","|qΔV|/m","√(|qΔV|/2m)","2|qΔV|/m","Energy conservation gives ΔK=−ΔU=|qΔV|. With Kf=½mv² from rest, solving ½mv²=|qΔV| yields v=√(2|qΔV|/m).");
add("em-9.3-04","U9","9.3","Conservation of Electric Energy","2.C","Two particles with equal mass and charge magnitudes +q and −q are each released from rest through potential changes chosen so that each loses the same electric potential energy. Their final speeds are","equal","larger for +q","larger for −q","not comparable without knowing the path shape","If each particle loses the same amount of electric potential energy, energy conservation gives each the same kinetic-energy gain; equal masses therefore lead to equal final speeds.");


add("em-10.1-01","U10","10.1","Electrostatics with Conductors","3.B","A solid conductor is in electrostatic equilibrium with no current flowing through it. Which statement about the electric field inside the conducting material is correct?","The electric field is zero","The field points toward the conductor's center","The field is uniform but nonzero","The field equals the surface charge density divided by ε₀ throughout the material","If a nonzero electric field existed inside the conducting material, mobile charges would accelerate and the conductor would not be in electrostatic equilibrium; therefore the interior field must be zero.");
add("em-10.1-02","U10","10.1","Electrostatics with Conductors","3.C","A charged conductor in electrostatic equilibrium has excess charge on its surface. Which reasoning best justifies this result?","Excess charge in the conducting bulk would create an internal field that drives charge until equilibrium is restored","Charge is pulled to the surface by gravity","The conductor's center cannot contain electric potential","Surface charge appears because the electric field outside every conductor is zero","Electrostatic equilibrium requires zero electric field within the conducting material; mobile excess charge therefore redistributes until no bulk field remains, leaving net excess charge on the surface.");
add("em-10.1-03","U10","10.1","Electrostatics with Conductors","2.B","The electric field immediately outside a conducting surface in vacuum is 3.0×10⁴ N/C and is normal to the surface. What is the local surface charge density?","2.66×10⁻⁷ C/m²","3.39×10¹⁵ C/m²","8.85×10⁻¹² C/m²","3.0×10⁴ C/m²","Immediately outside a conductor, E=σ/ε₀. Thus σ=ε₀E=(8.85×10⁻¹²)(3.0×10⁴)≈2.66×10⁻⁷ C/m², with sign set by the outward field direction.");
add("em-10.1-04","U10","10.1","Electrostatics with Conductors","2.C","Two points lie within the material of the same conductor in electrostatic equilibrium. Compared with one another, their electric potentials are","equal","larger at the point closer to the surface","smaller at the point closer to the surface","equal only if the conductor is spherical","Because the electric field inside the conducting material is zero and E=−∇V, the potential has no spatial gradient there; the entire connected conductor is an equipotential.");
add("em-10.2-01","U10","10.2","Redistribution of Charge between Conductors","3.B","Two well-separated conducting spheres of different radii are connected by a thin conducting wire and allowed to reach electrostatic equilibrium. Which quantity must be equal for the two spheres?","Electric potential","Surface electric field","Surface charge density","Total charge","Connected conductors exchange charge until there is no potential difference to drive further motion, so their electric potentials become equal even though their charges and surface fields can differ.");
add("em-10.2-02","U10","10.2","Redistribution of Charge between Conductors","2.A","Two well-separated conducting spheres of radii R and 2R are connected and carry total charge Q. Neglecting mutual influence, which charges satisfy equal potential and charge conservation?","Q/3 on the R sphere and 2Q/3 on the 2R sphere","Q/2 on each sphere","2Q/3 on the R sphere and Q/3 on the 2R sphere","Q/5 on the R sphere and 4Q/5 on the 2R sphere","For an isolated sphere V=kq/R. Equal potential gives q₁/R=q₂/(2R), so q₂=2q₁; together with q₁+q₂=Q this yields q₁=Q/3 and q₂=2Q/3.");
add("em-10.2-03","U10","10.2","Redistribution of Charge between Conductors","2.C","For two connected spheres of radii R and 2R at equal potential, how do their surface electric-field magnitudes compare after equilibrium?","The smaller sphere's surface field is twice the larger sphere's","The larger sphere's surface field is twice the smaller sphere's","The surface fields are equal","The smaller sphere's surface field is four times the larger sphere's","At equal potential q is proportional to R. Since a sphere's surface field is kq/R², E is proportional to 1/R; therefore the radius-R sphere has twice the surface field of the radius-2R sphere.");
add("em-10.2-04","U10","10.2","Redistribution of Charge between Conductors","2.D","Two isolated spherical conductors differ only in radius, with one having twice the radius. If each is raised to the same electric potential relative to infinity, how do their stored charges compare?","The larger sphere stores twice as much charge","The larger sphere stores four times as much charge","They store the same charge","The larger sphere stores half as much charge","An isolated sphere has capacitance C=4πε₀R and Q=CV. At fixed V, charge is proportional to radius, so doubling R doubles the charge required to reach the same potential.");


add("em-10.3-01","U10","10.3","Capacitors","2.B","A capacitor stores 6.0 μC when the potential difference across it is 12 V. What is its capacitance?","0.50 μF","2.0 μF","72 μF","0.072 μF","Capacitance is C=Q/ΔV, so C=(6.0 μC)/(12 V)=0.50 μF. The result depends on capacitor geometry and dielectric, not on the particular stored charge alone.");
add("em-10.3-02","U10","10.3","Capacitors","2.A","Ignoring fringing, which expression gives the capacitance of a vacuum parallel-plate capacitor with plate area A and separation d?","C = ε₀A/d","C = ε₀d/A","C = A/(ε₀d)","C = ε₀Ad","For oppositely charged parallel plates, E=σ/ε₀ and ΔV=Ed=Qd/(ε₀A). Substituting into C=Q/ΔV gives C=ε₀A/d.");
add("em-10.3-03","U10","10.3","Capacitors","2.B","A 4.0 μF capacitor is charged to 10 V. How much energy is stored in its electric field?","2.0×10⁻⁴ J","4.0×10⁻⁴ J","2.0×10⁻⁵ J","4.0×10⁻⁵ J","Capacitor energy is U=½CV²=½(4.0×10⁻⁶ F)(10 V)²=2.0×10⁻⁴ J, representing energy stored in the electric field between the conductors.");
add("em-10.3-04","U10","10.3","Capacitors","2.D","For an isolated parallel-plate capacitor with fixed charge, the plate separation is doubled while area is unchanged. By what factor does the stored electric energy change?","It doubles","It halves","It quadruples","It remains unchanged","For fixed charge U=Q²/(2C), while C=ε₀A/d. Doubling d halves capacitance, so stored energy doubles because mechanical work is done separating the attracting plates.");
add("em-10.4-01","U10","10.4","Dielectrics","3.B","A dielectric slab completely fills a parallel-plate capacitor while the capacitor remains connected to an ideal battery. Which statement is correct after insertion?","Capacitance and stored charge increase while voltage remains fixed","Capacitance increases while stored charge remains fixed","Voltage increases while capacitance remains fixed","Stored charge decreases while voltage remains fixed","The dielectric increases capacitance by the factor κ. The ideal battery holds the potential difference fixed, so Q=CV increases as additional charge flows from the battery onto the plates.");
add("em-10.4-02","U10","10.4","Dielectrics","3.C","A charged capacitor is disconnected from its battery before a dielectric is inserted fully between its plates. Why does the voltage decrease?","The free charge remains fixed while the dielectric increases capacitance, so V=Q/C decreases","The dielectric removes free charge from the plates","The dielectric decreases capacitance and therefore lowers voltage","The battery absorbs electric potential from the capacitor","Once disconnected, no conducting path exists for free plate charge to change. Polarization increases capacitance by κ, and with Q fixed the relation V=Q/C requires potential difference to fall.");
add("em-10.4-03","U10","10.4","Dielectrics","2.A","A dielectric of relative permittivity κ completely fills the gap of a parallel-plate capacitor of area A and separation d. Which expression gives its capacitance?","C = κε₀A/d","C = ε₀A/(κd)","C = κε₀d/A","C = ε₀A/d","A linear dielectric reduces the internal field for a given free charge by polarization, increasing capacitance by factor κ relative to vacuum; therefore C=κε₀A/d.");
add("em-10.4-04","U10","10.4","Dielectrics","2.D","A capacitor remains connected to a fixed-voltage battery while a dielectric with κ=3 is inserted fully. By what factor does the stored electric energy change?","It increases by a factor of 3","It decreases by a factor of 3","It increases by a factor of 9","It remains unchanged","At fixed battery voltage U=½CV². Full dielectric insertion multiplies capacitance by κ=3 while V remains fixed, so stored energy increases by the same factor of 3.");

add("em-11.1-01","U11","11.1","Electric Current","2.B","A steady current of 3.0 A flows through a wire for 4.0 s. How much charge passes a cross section of the wire?","12 C","0.75 C","7 C","1.33 C","For steady current, I=ΔQ/Δt, so ΔQ=IΔt=(3.0 A)(4.0 s)=12 C. Current measures the rate at which net charge crosses a chosen surface.");
add("em-11.1-02","U11","11.1","Electric Current","2.A","The current in a wire varies with time as I(t)=I₀e^(−t/τ). Which expression gives the charge that passes a cross section from t=0 to t=T?","I₀τ(1−e^(−T/τ))","I₀T e^(−T/τ)","I₀τe^(−T/τ)","I₀T/τ","Because current is dQ/dt, transferred charge is ∫₀ᵀI(t)dt. Integrating the exponential gives I₀τ[1−e^(−T/τ)], with units of amperes times seconds, or coulombs.");
add("em-11.1-03","U11","11.1","Electric Current","2.C","Two wires carry the same conventional current. Wire B has twice the cross-sectional area of wire A and the same charge-carrier density. How do their drift speeds compare?","The drift speed in B is half that in A","The drift speed in B is twice that in A","The drift speeds are equal","The drift speed in B is four times that in A","Using I=nqAv_d, fixed current, carrier density, and carrier charge imply v_d is inversely proportional to area. Doubling A therefore halves the drift speed.");
add("em-11.1-04","U11","11.1","Electric Current","3.B","Electrons in a metal drift opposite the direction of conventional current. Which statement best explains this?","Conventional current is defined in the direction positive charge would move","Electrons experience no electric force in a current-carrying wire","Conventional current always points opposite the electric field","Positive ions move through the lattice faster than electrons","Conventional current direction is defined by hypothetical positive-charge motion. Because electron charge is negative, their average drift under an electric field is opposite that conventional-current direction.");
add("em-11.2-01","U11","11.2","Simple Circuits","2.B","An ideal 12 V battery is connected across a 4.0 Ω resistor. What current flows through the resistor?","3.0 A","48 A","0.33 A","8.0 A","For an ideal source and one resistor, Ohm's law gives I=V/R=(12 V)/(4.0 Ω)=3.0 A. The full battery potential difference appears across the resistor.");
add("em-11.2-02","U11","11.2","Simple Circuits","2.C","Two identical resistors are connected first in series and then in parallel across the same ideal battery. How does the total current in the parallel arrangement compare with the series arrangement?","It is four times as large","It is twice as large","It is half as large","It is the same","For two identical resistors R, series resistance is 2R while parallel resistance is R/2. At fixed battery voltage I=V/Req, so the parallel total current is four times the series current.");
add("em-11.2-03","U11","11.2","Simple Circuits","2.A","Three resistors R₁, R₂, and R₃ are connected in parallel. Which expression gives the equivalent resistance?","R_eq = (1/R₁ + 1/R₂ + 1/R₃)⁻¹","R_eq = R₁ + R₂ + R₃","R_eq = (R₁R₂R₃)⁻¹","R_eq = (R₁+R₂+R₃)/3","Parallel branches share the same voltage while branch currents add. Applying I_total=V(1/R₁+1/R₂+1/R₃)=V/R_eq yields the reciprocal-sum expression.");
add("em-11.2-04","U11","11.2","Simple Circuits","3.C","A student says adding another resistor in parallel to an ideal-battery circuit will reduce the battery's total current. Which response is best?","Adding a parallel path lowers equivalent resistance, so an ideal battery supplies more total current","Adding a parallel path raises equivalent resistance, so total current falls","The total current cannot change because battery voltage is fixed","The new branch receives current only if all existing branches have equal resistance","A new parallel branch adds positive conductance, decreasing equivalent resistance. With an ideal battery maintaining fixed voltage, I_total=V/R_eq therefore increases.");
add("em-11.3-01","U11","11.3","Resistance, Resistivity, and Ohm's Law","2.B","A uniform wire has resistivity 1.7×10⁻⁸ Ω·m, length 2.0 m, and cross-sectional area 1.0×10⁻⁶ m². What is its resistance?","0.034 Ω","0.017 Ω","0.068 Ω","34 Ω","For a uniform conductor, R=ρL/A=(1.7×10⁻⁸)(2.0)/(1.0×10⁻⁶)=3.4×10⁻² Ω, so the resistance is 0.034 Ω.");
add("em-11.3-02","U11","11.3","Resistance, Resistivity, and Ohm's Law","2.D","A wire is stretched so its length doubles while its volume and resistivity remain constant. By what factor does its resistance change?","It increases by a factor of 4","It increases by a factor of 2","It decreases by a factor of 2","It remains unchanged","Constant volume means doubling length halves cross-sectional area. Since R=ρL/A, the doubled numerator and halved denominator combine to make resistance four times larger.");
add("em-11.3-03","U11","11.3","Resistance, Resistivity, and Ohm's Law","2.C","Two wires have equal length and area. Wire B has twice the resistivity of wire A. Under the same potential difference, how do their currents compare?","Wire B carries half the current of wire A","Wire B carries twice the current of wire A","The currents are equal","Wire B carries one fourth the current of wire A","Equal geometry gives R proportional to resistivity, so wire B has twice the resistance. With the same applied voltage, I=V/R makes B's current half of A's.");
add("em-11.3-04","U11","11.3","Resistance, Resistivity, and Ohm's Law","3.B","A device has a nonlinear I-versus-V graph rather than a straight line through the origin. Which claim is best supported?","Its resistance is not constant over the measured voltage range","It cannot carry electric current","Its resistivity must be zero","Kirchhoff's junction rule does not apply to it","An ohmic element with constant resistance obeys V=IR and gives a straight-line I-V relation. Curvature means the ratio V/I changes with operating point, so resistance is not constant.");
add("em-11.4-01","U11","11.4","Electric Power","2.B","A 6.0 Ω resistor carries a current of 2.0 A. What rate is electrical energy converted to thermal energy in the resistor?","24 W","12 W","3 W","72 W","Resistive power can be written P=I²R. Substitution gives P=(2.0 A)²(6.0 Ω)=24 W, the rate at which electrical energy is dissipated.");
add("em-11.4-02","U11","11.4","Electric Power","2.A","Which expression gives the power dissipated by a resistor R directly in terms of the potential difference V across it?","P = V²/R","P = VR","P = R/V²","P = V/R²","Starting with P=IV and using Ohm's law I=V/R gives P=V(V/R)=V²/R, which is useful when the voltage across the resistor is known.");
add("em-11.4-03","U11","11.4","Electric Power","2.D","A resistor remains connected to an ideal fixed-voltage source while its resistance is doubled. By what factor does its power dissipation change?","It becomes one half as large","It doubles","It becomes one fourth as large","It remains unchanged","For fixed voltage, P=V²/R. Doubling R therefore divides the power by two; the current also falls by a factor of two.");
add("em-11.4-04","U11","11.4","Electric Power","3.C","Two resistors R and 2R are connected in series. A student claims the smaller resistor dissipates more power because its resistance is lower. Which response is correct?","The 2R resistor dissipates twice as much power because both carry the same current and P=I²R","The R resistor dissipates twice as much power because P=V²/R","They dissipate equal power because the current is the same","Power cannot be compared without knowing the battery voltage","Series elements carry the same current. Using P=I²R, the resistor with twice the resistance dissipates twice the power; the voltage division adjusts accordingly.");

add("em-11.5-01","U11","11.5","Compound Direct Current Circuits","2.B","A 6 Ω resistor is in series with a parallel combination of 6 Ω and 3 Ω across a 12 V ideal battery. What is the total current from the battery?","1.5 A","2.0 A","1.0 A","4.0 A","The parallel pair has equivalent resistance (1/6+1/3)⁻¹=2 Ω. In series with 6 Ω the total is 8 Ω, so I=12 V/8 Ω=1.5 A.");
add("em-11.5-02","U11","11.5","Compound Direct Current Circuits","2.C","In a circuit, resistor R is in series with a parallel pair R and R. Compared with the current through the series resistor, the current through either parallel resistor is","one half as large","the same","twice as large","one fourth as large","The full circuit current reaches the junction and divides equally between identical parallel branches. Each branch therefore carries half the current that passes through the series resistor.");
add("em-11.5-03","U11","11.5","Compound Direct Current Circuits","3.B","A parallel branch in a compound circuit is opened, leaving the remaining branches connected to an ideal battery. Which claim about the total current drawn from the battery is generally correct?","It decreases because the equivalent resistance increases","It increases because the equivalent resistance increases","It stays fixed because the battery voltage is fixed","It becomes zero even if other branches remain closed","Removing a conducting parallel path decreases total conductance and therefore raises equivalent resistance. An ideal battery keeps V fixed, so I_total=V/R_eq decreases.");
add("em-11.5-04","U11","11.5","Compound Direct Current Circuits","2.A","Resistor R₁ is in series with the parallel combination of R₂ and R₃. Which expression gives the circuit's equivalent resistance?","R₁ + R₂R₃/(R₂+R₃)","R₁R₂R₃/(R₁+R₂+R₃)","(R₁+R₂+R₃)/3","1/R₁ + 1/R₂ + 1/R₃","The parallel pair has resistance R₂R₃/(R₂+R₃). Because that equivalent element is in series with R₁, the two resistances add to give the stated expression.");

add("em-11.6-01","U11","11.6","Kirchhoff's Loop Rule","2.B","Traversing a loop in the direction of current through a 5.0 Ω resistor carrying 2.0 A, what potential change is assigned to the resistor?","−10 V","+10 V","−2.5 V","+2.5 V","Moving through a resistor in the direction of conventional current gives a potential drop −IR. Here −(2.0 A)(5.0 Ω)=−10 V.");
add("em-11.6-02","U11","11.6","Kirchhoff's Loop Rule","3.C","Why must the algebraic sum of potential changes around any closed steady-state circuit loop equal zero?","Returning to the starting point requires the electric potential to have the same value after one complete loop","Charge is destroyed in every resistor and recreated by the battery","All circuit elements must have the same resistance","The current must be identical in every branch of the circuit","Electric potential is single-valued. After traversing a closed path and returning to the same point, the net change in potential must be zero, which is Kirchhoff's loop rule.");
add("em-11.6-03","U11","11.6","Kirchhoff's Loop Rule","2.A","A loop contains an ideal emf ε and two series resistors R₁ and R₂. Which equation follows from Kirchhoff's loop rule for current I?","ε − IR₁ − IR₂ = 0","ε + IR₁ + IR₂ = 0","εR₁R₂ − I = 0","ε − I/(R₁+R₂) = 0","Traversing from the negative to positive battery terminal gives a rise +ε, while traversing each resistor with the current gives drops −IR₁ and −IR₂. Their algebraic sum is zero.");
add("em-11.6-04","U11","11.6","Kirchhoff's Loop Rule","3.B","When solving a multi-loop circuit, an assumed branch current is found to be negative. What does the negative sign mean?","The actual current flows opposite the initially assumed direction","The circuit violates conservation of energy","The branch carries no current","The resistor has negative resistance","Current directions may be assigned arbitrarily before writing loop equations. A negative solution simply means the physical current direction is opposite that assumed, not that any circuit law has failed.");

add("em-11.7-01","U11","11.7","Kirchhoff's Junction Rule","2.B","At a junction, currents of 2.0 A and 3.5 A enter while one current of 1.0 A leaves. What additional current must leave the junction?","4.5 A","6.5 A","3.5 A","2.5 A","Charge conservation requires total current entering to equal total current leaving. Thus 2.0+3.5=1.0+I, giving I=4.5 A.");
add("em-11.7-02","U11","11.7","Kirchhoff's Junction Rule","3.C","Which principle provides the physical basis for Kirchhoff's junction rule in a steady circuit?","Conservation of electric charge","Conservation of mechanical momentum","Conservation of magnetic flux","Conservation of electric potential energy in each resistor separately","If charge were to enter a junction faster than it left, charge would accumulate there and the circuit would not remain in steady state. Charge conservation therefore requires the sum of entering currents to equal the sum leaving.");
add("em-11.7-03","U11","11.7","Kirchhoff's Junction Rule","2.A","Using signed branch currents with positive values defined as leaving a junction, which equation expresses Kirchhoff's junction rule?","Σ I = 0","Σ IR = 0","Σ I²R = 0","Σ V = 0","The junction rule is a statement of zero net charge accumulation. With a consistent sign convention, the algebraic sum of all branch currents at the node is therefore zero.");
add("em-11.7-04","U11","11.7","Kirchhoff's Junction Rule","2.C","A current I enters a junction and splits into two branches. Branch A has twice the resistance of branch B, and both branches reconnect immediately afterward. How do their currents compare?","Branch B carries twice the current of branch A","Branch A carries twice the current of branch B","The branch currents are equal","Branch B carries four times the current of branch A","The two parallel branches share the same potential difference. Since I=V/R, the branch with half the resistance carries twice the current; the two branch currents still sum to the incoming current.");

add("em-11.8-01","U11","11.8","Resistor Capacitor (RC) Circuits","2.A","An initially uncharged capacitor C charges through resistor R from an ideal battery of emf ε. Which expression gives the capacitor charge as a function of time?","q(t)=Cε(1−e^(−t/RC))","q(t)=Cεe^(−t/RC)","q(t)=εR(1−e^(−t/RC))","q(t)=Cε(1+e^(−t/RC))","Solving the RC charging differential equation ε−q/C−R dq/dt=0 with q(0)=0 gives q=Cε(1−e^(−t/RC)); the time constant is RC.");
add("em-11.8-02","U11","11.8","Resistor Capacitor (RC) Circuits","2.B","A 2.0 μF capacitor discharges through a 3.0 MΩ resistor. What is the circuit time constant?","6.0 s","1.5 s","0.67 s","6.0×10⁻⁶ s","The RC time constant is τ=RC=(3.0×10⁶ Ω)(2.0×10⁻⁶ F)=6.0 s. After one time constant, charge and current have fallen to e⁻¹ of their initial values.");
add("em-11.8-03","U11","11.8","Resistor Capacitor (RC) Circuits","2.D","In an RC discharge circuit, both R and C are doubled while the initial capacitor voltage is unchanged. By what factor does the time constant change?","It increases by a factor of 4","It increases by a factor of 2","It decreases by a factor of 4","It remains unchanged","The time constant is τ=RC. Doubling both resistance and capacitance multiplies their product by 2×2=4, so the discharge proceeds four times more slowly in scaled time.");
add("em-11.8-04","U11","11.8","Resistor Capacitor (RC) Circuits","3.B","During charging of an initially uncharged series RC circuit connected to an ideal battery, which statement is correct as time increases?","The current decreases toward zero while the capacitor voltage increases toward the battery emf","The current increases while the capacitor voltage decreases","The current remains constant until the capacitor is fully charged","The capacitor voltage exceeds the battery emf at long times","As charge accumulates, the capacitor's opposing voltage rises, reducing the resistor voltage and current. At long times the current tends to zero and the capacitor voltage approaches the battery emf.");

add("em-12.1-01","U12","12.1","Magnetic Fields","3.B","A compass is placed near a long straight wire carrying conventional current upward. At a point directly east of the wire, which direction does the wire's magnetic field point?","north","south","upward","east","The right-hand rule with the thumb along the upward current makes the magnetic field circle the wire. At the point east of the wire, the tangent direction is north.");
add("em-12.1-02","U12","12.1","Magnetic Fields","2.C","At distances r and 2r from the same long straight current-carrying wire, how do the magnetic-field magnitudes compare?","The field at r is twice the field at 2r","The field at r is four times the field at 2r","The fields are equal","The field at 2r is twice the field at r","For a long straight wire B=μ₀I/(2πr), so field magnitude is inversely proportional to distance. Doubling r therefore halves B.");
add("em-12.1-03","U12","12.1","Magnetic Fields","2.B","A long straight wire carries 5.0 A. What is the magnetic-field magnitude 0.10 m from the wire?","1.0×10⁻⁵ T","5.0×10⁻⁵ T","1.0×10⁻⁶ T","2.5×10⁻⁵ T","Using B=μ₀I/(2πr) gives (4π×10⁻⁷)(5.0)/(2π×0.10)=1.0×10⁻⁵ T for the field at the specified distance.");
add("em-12.1-04","U12","12.1","Magnetic Fields","3.C","A student sketches magnetic-field lines that begin on a north magnetic pole and terminate on a south pole without continuing through the magnet. What is wrong with the sketch?","Magnetic-field lines form continuous closed loops rather than having isolated beginnings or endings","Magnetic-field lines can terminate only in empty space","Magnetic-field lines must be straight near every magnet","Magnetic fields exist only when electric current is visible","Magnetic-field lines represent a divergence-free magnetic field and therefore form continuous loops; outside a bar magnet they run north to south and continue through the magnet.");

add("em-12.2-01","U12","12.2","Magnetism and Moving Charges","2.B","A proton moves at 3.0×10⁶ m/s perpendicular to a 0.20 T magnetic field. What is the magnetic-force magnitude?","9.6×10⁻¹⁴ N","4.8×10⁻¹⁴ N","9.6×10⁻¹³ N","1.2×10⁻¹⁹ N","For perpendicular velocity and field, F=qvB=(1.60×10⁻¹⁹ C)(3.0×10⁶ m/s)(0.20 T)=9.6×10⁻¹⁴ N.");
add("em-12.2-02","U12","12.2","Magnetism and Moving Charges","2.A","A particle of mass m and charge magnitude |q| moves perpendicular to a uniform magnetic field B in a circle. Which expression gives the orbit radius?","r = mv/(|q|B)","r = |q|B/(mv)","r = mv²/(|q|B)","r = |q|v/(mB)","The magnetic force |q|vB supplies centripetal force mv²/r. Equating them and solving for radius gives r=mv/(|q|B).");
add("em-12.2-03","U12","12.2","Magnetism and Moving Charges","2.D","A charged particle moves perpendicular to a uniform magnetic field. If its speed doubles while B is unchanged, by what factor does its circular-orbit radius change?","It doubles","It quadruples","It halves","It remains unchanged","The orbit radius is r=mv/(|q|B), directly proportional to speed for fixed mass, charge, and field. Doubling v therefore doubles r.");
add("em-12.2-04","U12","12.2","Magnetism and Moving Charges","3.B","A charged particle moves exactly parallel to a uniform magnetic field. Which claim about the magnetic force is correct?","The magnetic force is zero","The force is maximum and parallel to the field","The force reverses the particle's velocity","The force magnitude is qvB regardless of direction","Magnetic force is qv×B with magnitude |q|vB sinθ. Parallel motion has θ=0, so the cross product and magnetic force are zero.");

add("em-12.3-01","U12","12.3","Magnetic Fields of Current-Carrying Wires and the Biot-Savart Law","2.A","Which differential expression is the Biot-Savart law for the magnetic field produced by a current element I dℓ at displacement vector r from the element?","dB = (μ₀/4π) I(dℓ×r̂)/r²","dB = (μ₀/4π) I dℓ/r","dB = μ₀I r̂/(2πr)","dB = (μ₀/4π) I(dℓ·r̂)/r²","The Biot-Savart law contains the vector cross product dℓ×r̂ and inverse-square dependence for each differential current element; integrating those contributions yields the total field.");
add("em-12.3-02","U12","12.3","Magnetic Fields of Current-Carrying Wires and the Biot-Savart Law","2.B","A circular loop of radius 0.20 m carries 4.0 A. What is the magnetic-field magnitude at its center?","1.26×10⁻⁵ T","2.51×10⁻⁵ T","4.0×10⁻⁶ T","1.00×10⁻⁵ T","For one circular loop, B_center=μ₀I/(2R)=(4π×10⁻⁷)(4.0)/(0.40)≈1.26×10⁻⁵ T.");
add("em-12.3-03","U12","12.3","Magnetic Fields of Current-Carrying Wires and the Biot-Savart Law","2.C","Two circular loops have the same current. Loop B has twice the radius of loop A. How do their magnetic fields at their centers compare?","Loop A's field is twice loop B's","Loop A's field is four times loop B's","The fields are equal","Loop B's field is twice loop A's","The center field of a circular loop is μ₀I/(2R), so at fixed current it is inversely proportional to radius. Doubling R halves the field.");
add("em-12.3-04","U12","12.3","Magnetic Fields of Current-Carrying Wires and the Biot-Savart Law","3.C","Why do current elements on opposite sides of a circular loop reinforce rather than cancel the magnetic field at the loop center?","Their Biot-Savart cross products point in the same axial direction at the center","Their current directions are identical vectors at opposite sides","Magnetic-field contributions are scalars and cannot cancel","The center is at zero distance from every current element","Although opposite current elements have opposite tangent directions, their displacement directions to the center also differ, so dℓ×r̂ points along the same loop-axis direction for all elements.");

add("em-12.4-01","U12","12.4","Ampère's Law","2.A","Which integral equation states Ampère's law for steady currents?","∮ B·dℓ = μ₀I_enc","∮ E·dA = Q_enc/ε₀","∮ B·dA = μ₀I_enc","∮ B·dℓ = I_enc/μ₀","Ampère's law relates the circulation of the magnetic field around a closed path to μ₀ times the net steady current passing through a surface bounded by that path.");
add("em-12.4-02","U12","12.4","Ampère's Law","2.B","An ideal long solenoid has 800 turns per meter and carries 2.0 A. What is the magnetic-field magnitude well inside it?","2.01×10⁻³ T","1.01×10⁻³ T","4.02×10⁻³ T","6.37×10⁻⁴ T","For an ideal long solenoid, Ampère's law gives B=μ₀nI=(4π×10⁻⁷)(800)(2.0)≈2.01×10⁻³ T.");
add("em-12.4-03","U12","12.4","Ampère's Law","2.D","For an ideal long solenoid, the turns per unit length are doubled and the current is tripled. By what factor does the interior magnetic field change?","It increases by a factor of 6","It increases by a factor of 5","It increases by a factor of 3","It doubles","The ideal-solenoid field B=μ₀nI is directly proportional to both turn density and current, so factors of 2 and 3 multiply to a factor of 6.");
add("em-12.4-04","U12","12.4","Ampère's Law","3.B","Why is a circular Amperian loop especially useful for finding the field around a very long straight wire?","Cylindrical symmetry makes B tangent to the loop with constant magnitude","The magnetic field is zero everywhere except on the loop","Ampère's law applies only to circular paths","The enclosed current must be uniformly spread over the loop itself","For an effectively infinite straight wire, rotational and translational symmetry make B depend only on radius and point tangentially. A concentric circle therefore lets B factor out of ∮B·dℓ.");

add("em-13.1-01","U13","13.1","Magnetic Flux","2.B","A uniform 0.80 T magnetic field is perpendicular to a 0.25 m² loop. What is the magnetic flux through the loop?","0.20 Wb","0.32 Wb","0.050 Wb","3.2 Wb","Magnetic flux is ΦB = BA cos θ, where θ is the angle between the field and area vector. Perpendicular field and loop means θ = 0°, so ΦB = (0.80)(0.25) = 0.20 Wb.");
add("em-13.1-02","U13","13.1","Magnetic Flux","2.D","A flat loop in a uniform magnetic field rotates from having its area vector parallel to the field to perpendicular to the field. The magnitude of its magnetic flux changes by what factor?","from BA to zero","from zero to BA","from BA to BA/2","it remains BA","Flux is ΦB = BA cos θ. Parallel area vector gives θ = 0° and flux BA; perpendicular area vector gives θ = 90° and zero flux.");
add("em-13.1-03","U13","13.1","Magnetic Flux","2.A","For a nonuniform magnetic field passing through a surface, which expression defines the magnetic flux?","ΦB = ∫ B·dA","ΦB = ∫ B dl","ΦB = B/A","ΦB = ∫ A·dB","Magnetic flux sums the normal component of magnetic field over differential surface elements, so the general definition is the surface integral ΦB = ∫ B·dA.");
add("em-13.1-04","U13","13.1","Magnetic Flux","3.B","A closed surface encloses a bar magnet. What is the net magnetic flux through the closed surface?","Zero","Positive because the north pole is enclosed","Negative because the south pole is enclosed","It depends on the magnet strength","Gauss's law for magnetism states ∮B·dA = 0 for every closed surface because isolated magnetic monopoles are not observed; field lines entering equal field lines leaving.");
add("em-13.2-01","U13","13.2","Electromagnetic Induction","2.B","The magnetic flux through a 20-turn coil decreases uniformly from 0.50 Wb to 0.10 Wb in 0.20 s. What is the magnitude of the induced emf?","40 V","8 V","2 V","200 V","Faraday's law gives |ε| = N|ΔΦB/Δt| = 20(0.40/0.20) = 40 V. The sign from Lenz's law describes polarity, not the requested magnitude.");
add("em-13.2-02","U13","13.2","Electromagnetic Induction","2.A","Which expression gives the instantaneous induced emf in an N-turn coil when the magnetic flux through each turn varies with time?","ε = −N dΦB/dt","ε = NΦB/t","ε = −dB/dx","ε = N dI/dt","Faraday's law states that induced emf equals the negative time rate of change of magnetic-flux linkage, giving ε = −N dΦB/dt for N identical turns.");
add("em-13.2-03","U13","13.2","Electromagnetic Induction","3.C","A north pole of a magnet approaches a conducting loop along its axis. Why does the induced current create a magnetic field opposing the approach?","Opposition is required by Lenz's law and energy conservation","The loop must attract every approaching magnetic pole","Magnetic flux through a conductor cannot change","The induced current always flows clockwise","Lenz's law makes the induced field oppose the change in flux. If it instead reinforced the approach without external work, magnetic interaction could create energy from nothing.");
add("em-13.2-04","U13","13.2","Electromagnetic Induction","2.D","A loop's area is doubled while the perpendicular magnetic field changes at the same rate dB/dt. How does the induced-emf magnitude change?","It doubles","It halves","It quadruples","It is unchanged","For fixed orientation, ΦB = BA and |ε| = |dΦB/dt| = A|dB/dt|. Doubling the loop area therefore doubles the induced-emf magnitude.");
add("em-13.3-01","U13","13.3","Induced Currents and Magnetic Forces","2.B","A conducting rod of length 0.40 m moves at 5.0 m/s perpendicular to a uniform 0.60 T magnetic field. What motional emf appears across the rod?","1.2 V","0.48 V","3.0 V","12 V","For a rod moving perpendicular to both its length and the field, motional emf is ε = BLv = (0.60)(0.40)(5.0) = 1.2 V.");
add("em-13.3-02","U13","13.3","Induced Currents and Magnetic Forces","3.B","A conducting rod slides right on rails through a uniform magnetic field into the page, completing a circuit. The magnetic force on the induced current in the rod points","left, opposing the rod's motion","right, reinforcing the rod's motion","up along the rod","into the page","As the loop area and inward flux increase, Lenz's law produces a current whose magnetic interaction resists the change. The resulting force on the moving rod points left.");
add("em-13.3-03","U13","13.3","Induced Currents and Magnetic Forces","2.A","A rod of length L moves with velocity v through magnetic field B. Which integral gives the motional emf between its ends in the general case?","ε = ∫(v×B)·dl","ε = ∫B·dA","ε = ∫E·dA","ε = ∫(B×dl)·v dt","Magnetic force q(v×B) separates charge along the moving conductor. The corresponding motional emf is the line integral ε = ∫(v×B)·dl along the rod.");
add("em-13.3-04","U13","13.3","Induced Currents and Magnetic Forces","2.D","A rod moves on rails in a fixed magnetic field and closed circuit. If its speed doubles while B, L, and circuit resistance remain constant, how does the magnetic drag force change?","It doubles","It quadruples","It is unchanged","It halves","Motional emf scales as BLv, so induced current scales as v. The magnetic force on the rod is ILB, adding another fixed BL factor; therefore force scales linearly with v, not quadratically.");
window.QUESTIONS_AP_PHYSICS_C_EM = E;
